        if (d == 0) {
            return s;
        }
        char[] arr = s.toCharArray();
        int n = arr.length;
        int i = 0;
        while (i < d) {
            char temp = arr[0];
            for (int j = 0; j < n - 1; j++) {
                arr[j] = arr[j + 1];
            }
            arr[n - 1] = temp;
            i++;
        }
        return new String(arr);
    }
}

