class BabylonianSquareroot {

    public static Double babylonianSquareroot(int number) {
        double n = number;
        double n2 = 0;
        while (true) {
            n2 = n * n;
            if (n2 == number) {
                return n;
            }
            if (n2 > number) {
                n = (n + number / n) / 2;
            } else {
                return (n + number / n) / 2;
            }
        }
    }
}

