class FirstElement {

    public static int firstElement(int[] arr, int n, int k) {
        if (arr == null || n == 0) {
            return -1; // Return -1 if the array is null or empty
        }

        Map<Integer, Integer> countMap = new LinkedHashMap<>(); // Maintain insertion order

        for (int i = 0; i < n; i++) {
            countMap.put(arr[i], countMap.getOrDefault(arr[i], 0) + 1);
        }

        for (int i = 0; i < n; i++) {
            if (countMap.get(arr[i]) != null && countMap.get(arr[i]) == k) {
