        for (int i = 0; i < str1.length(); i++) {
            if (str1.charAt(i) != str2.charAt(i)) {
                diff++;
            }
        }
        if (diff == 0) {
            return "0";
        }
        if ((diff & 1) == 1) {
            return "Not Possible";
        }
        return diff / 2;
    }
}

